        // Delete the item
        const deleted = await deleteMetaItem(ctx, itemUlid, itemType);

        if (!deleted) {
          error(`Failed to delete ${itemLabel}`);
          process.exit(1);
        }

        success(`Deleted ${itemLabel}`);
      } catch (err) {
        error('Failed to delete meta item', err);
        process.exit(1);
      }
    });
