      kspec('meta set @update-conv --add-rule "Rule 2"', tempDir);

      const convention = kspecJson<any>('meta get @update-conv', tempDir);
      expect(convention.rules).toContain('Rule 1');
      expect(convention.rules).toContain('Rule 2');
