      try {
        kspec('meta get @ref-agent', tempDir);
        expect.fail('Agent should be deleted');
      } catch (e: any) {
        expect(e.message).toContain('Meta item not found');
      }
    });

    it('should prevent deletion of workflow referenced by observation', () => {
