      execSync(
        `npx tsx ${CLI_PATH} item ac add @test-task-pending --given "g" --when "w" --then "t"`,
        { cwd: tempDir, encoding: 'utf-8', stdio: 'pipe' }
      );
    }).toThrow();
  });

  it('should update acceptance criterion', () => {
