  it('should error on invalid reference', () => {
    expect(() => {
      execSync(`npx tsx ${CLI_PATH} log @nonexistent-ref`, {
        cwd: tempDir,
        encoding: 'utf-8',
        stdio: ['pipe', 'pipe', 'pipe'],
      });
    }).toThrow();
  });

  // AC: @cmd-log ac-3
  it('should show no commits found message', () => {
    const output = kspec('log @test-task-pending', tempDir);
