async function sessionStartAction(options: SessionOptions): Promise<void> {
  try {
    const ctx = await initContext();

    // AC-2: Pull remote changes before showing session context
    let syncResult: ShadowSyncResult | null = null;
    if (ctx.shadow?.enabled) {
      syncResult = await shadowPull(ctx.shadow.worktreeDir);
      // AC-3: Warn about conflicts but continue with local state
      if (syncResult.hadConflict) {
        console.log(
          chalk.yellow('⚠ Shadow sync conflict detected. Run `kspec shadow resolve` to fix.')
        );
        console.log(chalk.gray('  Continuing with local state...'));
        console.log('');
      } else if (syncResult.pulled) {
        console.log(chalk.gray('ℹ Synced shadow branch from remote'));
      }
    }

    const sessionCtx = await gatherSessionContext(ctx, options);

    output(sessionCtx, () => formatSessionContext(sessionCtx, options));
  } catch (err) {
    error('Failed to gather session context', err);
    process.exit(1);
  }
}

/**
 * Read stdin if available (non-blocking check for hook input)
 */
async function readStdinIfAvailable(): Promise<string | null> {
  // Check if stdin is a TTY (interactive) - if so, don't try to read
  if (process.stdin.isTTY) {
    return null;
  }

  return new Promise((resolve) => {
    let data = '';
    const timeout = setTimeout(() => {
      process.stdin.removeAllListeners();
      resolve(data || null);
    }, 100); // 100ms timeout for stdin

    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => {
      data += chunk;
    });
    process.stdin.on('end', () => {
      clearTimeout(timeout);
      resolve(data || null);
    });
    process.stdin.on('error', () => {
      clearTimeout(timeout);
      resolve(null);
    });
    process.stdin.resume();
  });
}

/**
 * Parse Claude Code hook input from stdin
 */
function parseHookInput(stdin: string | null): StopHookInput | null {
  if (!stdin) return null;
  try {
    return JSON.parse(stdin.trim()) as StopHookInput;
  } catch {
    return null;
  }
}

// ─── Prompt Check (UserPromptSubmit Hook) ────────────────────────────────────

/**
 * Output spec-first reminder for UserPromptSubmit hook.
 *
 * This is a simple context injection - always outputs the reminder,
 * and Claude (Opus) is smart enough to apply it when relevant.
 */
async function sessionPromptCheckAction(): Promise<void> {
  // Lean, instructive reminder with kspec prefix
  console.log(
    '[kspec] Before implementing behavior changes, check spec coverage. Update spec first if needed.'
  );
}

async function sessionCheckpointAction(options: CheckpointOptions): Promise<void> {
  try {
    // Read stdin for Claude Code hook input
    const stdin = await readStdinIfAvailable();
    const hookInput = parseHookInput(stdin);

    // Check if this is a retry (stop hook already active)
    if (hookInput?.stop_hook_active) {
      options.stopHookActive = true;
    }

    const ctx = await initContext();
    const result = await performCheckpoint(ctx, options);

    // Output format depends on mode:
    // - JSON mode (--json): Output Claude Code hook format {"decision": "block", "reason": "..."}
    // - Human mode: Output formatted checkpoint result
    if (isJsonMode()) {
      if (!result.ok) {
        // Build reason message with issues and instructions
        const issueLines = result.issues.map(i => `- ${i.description}`).join('\n');
        const instructionLines = result.instructions.filter(i => i.trim()).join('\n');
        const reason = `${result.message}\n\nIssues:\n${issueLines}\n\n${instructionLines}`;
        console.log(JSON.stringify({ decision: 'block', reason }));
      }
      // If ok, exit silently (Claude Code expects no output when allowing stop)
    } else {
      formatCheckpointResult(result);
      if (!result.ok) {
        process.exit(1);
      }
    }
  } catch (err) {
    error('Failed to run checkpoint', err);
    process.exit(1);
  }
}

/**
 * Register the 'session' command group and aliases
 */
export function registerSessionCommands(program: Command): void {
  const session = program
    .command('session')
    .description('Session management and context');

  session
    .command('start')
    .alias('resume')
    .description('Surface relevant context for starting a new working session')
    .option('--brief', 'Compact summary (default)')
    .option('--full', 'Comprehensive context dump')
    .option('--since <time>', 'Filter by recency (ISO8601 or relative: 1h, 2d, 1w)')
    .option('--no-git', 'Skip git commit information')
    .option('-n, --limit <n>', 'Limit items per section', '5')
    .action(sessionStartAction);

  session
    .command('checkpoint')
    .description('Pre-stop hook: check for uncommitted work before ending session')
    .option('--force', 'Allow session end regardless of issues')
    .action(sessionCheckpointAction);

  session
    .command('prompt-check')
    .description('UserPromptSubmit hook: inject spec-first reminder')
    .action(sessionPromptCheckAction);

  // Top-level alias: kspec context
  program
    .command('context')
    .description('Alias for session start - surface session context')
    .option('--brief', 'Compact summary (default)')
    .option('--full', 'Comprehensive context dump')
    .option('--since <time>', 'Filter by recency (ISO8601 or relative: 1h, 2d, 1w)')
    .option('--no-git', 'Skip git commit information')
    .option('-n, --limit <n>', 'Limit items per section', '5')
    .action(sessionStartAction);
}

import { Command } from 'commander';
import { ulid } from 'ulid';
import {
  initContext,
  loadAllTasks,
  loadAllItems,
  saveTask,
  deleteTask,
  createTask,
  createNote,
  createTodo,
  syncSpecImplementationStatus,
  ReferenceIndex,
  checkSlugUniqueness,
  type LoadedTask,
} from '../../parser/index.js';
import { commitIfShadow } from '../../parser/shadow.js';
import {
  output,
  formatTaskDetails,
  success,
  error,
  warn,
  info,
  isJsonMode,
} from '../output.js';
import { formatCommitGuidance, printCommitGuidance } from '../../utils/commit.js';
import type { Task, TaskInput } from '../../schema/index.js';

/**
 * Find a task by reference with detailed error reporting.
 * Returns the task or exits with appropriate error.
 */
function resolveTaskRef(
  ref: string,
  tasks: LoadedTask[],
  index: ReferenceIndex
): LoadedTask {
  const result = index.resolve(ref);

  if (!result.ok) {
    switch (result.error) {
      case 'not_found':
        error(`Task not found: ${ref}`);
        break;
      case 'ambiguous':
        error(`Reference "${ref}" is ambiguous. Matches:`);
        for (const candidate of result.candidates) {
          const task = tasks.find(t => t._ulid === candidate);
          const slug = task?.slugs[0] || '';
          console.error(`  - ${index.shortUlid(candidate)} ${slug ? `(${slug})` : ''}`);
        }
        break;
      case 'duplicate_slug':
        error(`Slug "${ref}" maps to multiple items. Use ULID instead:`);
        for (const candidate of result.candidates) {
          console.error(`  - ${index.shortUlid(candidate)}`);
        }
        break;
    }
    process.exit(3);
  }

  // Check if it's actually a task
  const task = tasks.find(t => t._ulid === result.ulid);
  if (!task) {
    error(`Reference "${ref}" is not a task (it's a spec item)`);
    process.exit(3);
  }

  return task;
}

/**
 * Register the 'task' command group (singular - operations on individual tasks)
 */
export function registerTaskCommands(program: Command): void {
  const task = program
    .command('task')
    .description('Operations on individual tasks');

  // kspec task get <ref>
  task
    .command('get <ref>')
    .description('Get task details')
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        output(foundTask, () => formatTaskDetails(foundTask, index));
      } catch (err) {
        error('Failed to get task', err);
        process.exit(1);
      }
    });

  // kspec task add
  task
    .command('add')
    .description('Create a new task')
    .requiredOption('--title <title>', 'Task title')
    .option('--type <type>', 'Task type (task, epic, bug, spike, infra)', 'task')
    .option('--spec-ref <ref>', 'Reference to spec item')
    .option('--meta-ref <ref>', 'Reference to meta item (workflow, agent, or convention)')
    .option('--priority <n>', 'Priority (1-5)', '3')
    .option('--slug <slug>', 'Human-friendly slug')
    .option('--tag <tag...>', 'Tags')
    .action(async (options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);

        // Load meta items for validation
        const { loadMetaContext } = await import('../../parser/meta.js');
        const metaContext = await loadMetaContext(ctx);
        const allMetaItems = [
          ...metaContext.agents,
          ...metaContext.workflows,
          ...metaContext.conventions,
          ...metaContext.observations,
        ];

        // Build index for reference validation
        const refIndex = new ReferenceIndex(tasks, items, allMetaItems);

        // Check slug uniqueness if provided
        if (options.slug) {
          const slugCheck = checkSlugUniqueness(refIndex, [options.slug]);
          if (!slugCheck.ok) {
            error(`Slug '${slugCheck.slug}' already exists (used by ${slugCheck.existingUlid})`);
            process.exit(1);
          }
        }

        // Validate meta_ref if provided (AC-meta-ref-3, AC-meta-ref-4)
        if (options.metaRef) {
          const metaRefResult = refIndex.resolve(options.metaRef);

          if (!metaRefResult.ok) {
            error(`meta_ref '${options.metaRef}' does not resolve to a valid meta item (agent, workflow, or convention)`);
            process.exit(3);
          }

          // Check if the resolved item is a meta item (not a spec item or task)
          const isTask = tasks.some(t => t._ulid === metaRefResult.ulid);
          const isSpecItem = items.some(i => i._ulid === metaRefResult.ulid);

          if (isTask || isSpecItem) {
            error(`meta_ref '${options.metaRef}' points to a spec item; use --spec-ref for product spec references`);
            process.exit(3);
          }
        }

        const input: TaskInput = {
          title: options.title,
          type: options.type,
          spec_ref: options.specRef || null,
          meta_ref: options.metaRef || null,
          priority: parseInt(options.priority, 10),
          slugs: options.slug ? [options.slug] : [],
          tags: options.tag || [],
        };

        const newTask = createTask(input);
        await saveTask(ctx, newTask);
        await commitIfShadow(ctx.shadow, 'task-add', newTask.slugs[0] || newTask._ulid.slice(0, 8), newTask.title);

        // Build index including the new task for accurate short ULID
        const index = new ReferenceIndex([...tasks, newTask], items, allMetaItems);
        success(`Created task: ${index.shortUlid(newTask._ulid)}`, { task: newTask });
      } catch (err) {
        error('Failed to create task', err);
        process.exit(1);
      }
    });

  // kspec task set <ref>
  task
    .command('set <ref>')
    .description('Update task fields')
    .option('--title <title>', 'Update task title')
    .option('--spec-ref <ref>', 'Link to spec item')
    .option('--meta-ref <ref>', 'Link to meta item (workflow, agent, or convention)')
    .option('--priority <n>', 'Set priority (1-5)')
    .option('--slug <slug>', 'Add a slug alias')
    .option('--tag <tag...>', 'Add tags')
    .option('--depends-on <refs...>', 'Set dependencies (replaces existing)')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);

        // Load meta items for validation
        const { loadMetaContext } = await import('../../parser/meta.js');
        const metaContext = await loadMetaContext(ctx);
        const allMetaItems = [
          ...metaContext.agents,
          ...metaContext.workflows,
          ...metaContext.conventions,
          ...metaContext.observations,
        ];

        const index = new ReferenceIndex(tasks, items, allMetaItems);
        const foundTask = resolveTaskRef(ref, tasks, index);

        // Check slug uniqueness if adding a new slug
        if (options.slug) {
          const slugCheck = checkSlugUniqueness(index, [options.slug], foundTask._ulid);
          if (!slugCheck.ok) {
            error(`Slug '${slugCheck.slug}' already exists (used by ${slugCheck.existingUlid})`);
            process.exit(1);
          }
        }

        // Build updated task with only provided options
        const updatedTask: Task = { ...foundTask };
        const changes: string[] = [];

        if (options.title) {
          updatedTask.title = options.title;
          changes.push('title');
        }

        if (options.specRef) {
          // Validate the spec ref exists and is a spec item
          const specResult = index.resolve(options.specRef);
          if (!specResult.ok) {
            error(`Spec reference not found: ${options.specRef}`);
            process.exit(3);
          }
          // Check it's not a task
          const isTask = tasks.some(t => t._ulid === specResult.ulid);
          if (isTask) {
            error(`Reference "${options.specRef}" is a task, not a spec item`);
            process.exit(3);
          }
          updatedTask.spec_ref = options.specRef;
          changes.push('spec_ref');
        }

        if (options.metaRef) {
          // Validate the meta ref exists and is a meta item
          const metaRefResult = index.resolve(options.metaRef);
          if (!metaRefResult.ok) {
            error(`meta_ref '${options.metaRef}' does not resolve to a valid meta item (agent, workflow, or convention)`);
            process.exit(3);
          }

          // Check if the resolved item is a meta item (not a spec item or task)
          const isTask = tasks.some(t => t._ulid === metaRefResult.ulid);
          const isSpecItem = items.some(i => i._ulid === metaRefResult.ulid);

          if (isTask || isSpecItem) {
            error(`meta_ref '${options.metaRef}' points to a spec item; use --spec-ref for product spec references`);
            process.exit(3);
          }

          updatedTask.meta_ref = options.metaRef;
          changes.push('meta_ref');
        }

        if (options.priority) {
          const priority = parseInt(options.priority, 10);
          if (isNaN(priority) || priority < 1 || priority > 5) {
            error('Priority must be between 1 and 5');
            process.exit(3);
          }
          updatedTask.priority = priority;
          changes.push('priority');
        }

        if (options.slug) {
          if (!updatedTask.slugs.includes(options.slug)) {
            updatedTask.slugs = [...updatedTask.slugs, options.slug];
            changes.push('slug');
          }
        }

        if (options.tag) {
          const newTags = options.tag.filter((t: string) => !updatedTask.tags.includes(t));
          if (newTags.length > 0) {
            updatedTask.tags = [...updatedTask.tags, ...newTags];
            changes.push('tags');
          }
        }

        if (options.dependsOn) {
          // Validate all dependency refs
          for (const depRef of options.dependsOn) {
            const depResult = index.resolve(depRef);
            if (!depResult.ok) {
              error(`Dependency reference not found: ${depRef}`);
              process.exit(3);
            }
          }
          updatedTask.depends_on = options.dependsOn;
          changes.push('depends_on');
        }

        if (changes.length === 0) {
          warn('No changes specified');
          return;
        }

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-set', foundTask.slugs[0] || index.shortUlid(foundTask._ulid), changes.join(', '));
        success(`Updated task: ${index.shortUlid(updatedTask._ulid)} (${changes.join(', ')})`, { task: updatedTask });
      } catch (err) {
        error('Failed to update task', err);
        process.exit(1);
      }
    });

  // kspec task patch <ref>
  task
    .command('patch <ref>')
    .description('Update task with JSON data')
    .option('--data <json>', 'JSON object with fields to update')
    .option('--dry-run', 'Show what would change without writing')
    .option('--allow-unknown', 'Allow unknown fields (for extending format)')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);

        // Load meta items for validation
        const { loadMetaContext } = await import('../../parser/meta.js');
        const metaContext = await loadMetaContext(ctx);
        const allMetaItems = [
          ...metaContext.agents,
          ...metaContext.workflows,
          ...metaContext.conventions,
          ...metaContext.observations,
        ];

        const index = new ReferenceIndex(tasks, items, allMetaItems);
        const foundTask = resolveTaskRef(ref, tasks, index);

        // Get JSON data from --data flag or stdin
        let jsonData: string;
        if (options.data) {
          jsonData = options.data;
        } else {
          // Read from stdin
          const chunks: Buffer[] = [];
          for await (const chunk of process.stdin) {
            chunks.push(chunk);
          }
          jsonData = Buffer.concat(chunks).toString('utf-8');
        }

        // Parse JSON
        let patchData: Record<string, unknown>;
        try {
          patchData = JSON.parse(jsonData);
        } catch (parseErr) {
          error('Invalid JSON syntax', parseErr);
          process.exit(1);
        }

        // Validate against TaskInputSchema (partial)
        const { TaskInputSchema } = await import('../../schema/index.js');

        // Create a partial schema for validation
        const partialSchema = options.allowUnknown
          ? TaskInputSchema.partial().passthrough()
          : TaskInputSchema.partial().strict();

        let validatedPatch: Partial<TaskInput>;
        try {
          validatedPatch = partialSchema.parse(patchData);
        } catch (validationErr) {
          error('Invalid patch data', validationErr);
          process.exit(1);
        }

        // Check for unknown fields if strict mode
        if (!options.allowUnknown) {
          const knownFields = Object.keys(TaskInputSchema.shape);
          const providedFields = Object.keys(patchData);
          const unknownFields = providedFields.filter(f => !knownFields.includes(f));

          if (unknownFields.length > 0) {
            error(`Unknown field(s): ${unknownFields.join(', ')}`);
            process.exit(1);
          }
        }

        // Build updated task
        const updatedTask: Task = { ...foundTask, ...validatedPatch };

        // Track changes for output
        const changes = Object.keys(validatedPatch);

        if (options.dryRun) {
          info('Dry run - no changes will be written');
          info(`Would update: ${changes.join(', ')}`);
          output({ changes, updated: updatedTask }, () => {
            console.log(`\nChanges: ${changes.join(', ')}\n`);
            return formatTaskDetails(updatedTask, index);
          });
          return;
        }

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-patch', foundTask.slugs[0] || index.shortUlid(foundTask._ulid), changes.join(', '));
        success(`Patched task: ${index.shortUlid(updatedTask._ulid)} (${changes.join(', ')})`, { task: updatedTask });
      } catch (err) {
        error('Failed to patch task', err);
        process.exit(1);
      }
    });

  // kspec task start <ref>
  task
    .command('start <ref>')
    .description('Start working on a task (pending -> in_progress)')
    .option('--no-sync', 'Skip syncing spec implementation status')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status === 'in_progress') {
          warn('Task is already in progress');
          output(foundTask, () => formatTaskDetails(foundTask));
          return;
        }

        if (foundTask.status !== 'pending') {
          error(`Cannot start task with status: ${foundTask.status}`);
          process.exit(4); // Exit code 4 = invalid state
        }

        // Update status
        const updatedTask: Task = {
          ...foundTask,
          status: 'in_progress',
          started_at: new Date().toISOString(),
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-start', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Started task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });

        // Sync spec implementation status (unless --no-sync)
        if (options.sync !== false && foundTask.spec_ref) {
          const updatedTasks = tasks.map(t =>
            t._ulid === updatedTask._ulid ? { ...t, ...updatedTask } : t
          );
          const syncResult = await syncSpecImplementationStatus(
            ctx,
            updatedTask as LoadedTask,
            updatedTasks as LoadedTask[],
            items,
            index
          );
          if (syncResult) {
            info(`Synced spec "${syncResult.specTitle}" implementation: ${syncResult.previousStatus} -> ${syncResult.newStatus}`);
          }
        }
      } catch (err) {
        error('Failed to start task', err);
        process.exit(1);
      }
    });

  // kspec task complete <ref>
  task
    .command('complete <ref>')
    .description('Complete a task (in_progress -> completed)')
    .option('--reason <reason>', 'Completion reason/notes')
    .option('--no-sync', 'Skip syncing spec implementation status')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status === 'completed') {
          warn('Task is already completed');
          output(foundTask, () => formatTaskDetails(foundTask));
          return;
        }

        if (foundTask.status !== 'in_progress' && foundTask.status !== 'pending') {
          error(`Cannot complete task with status: ${foundTask.status}`);
          process.exit(4);
        }

        const now = new Date().toISOString();

        // Update status
        const updatedTask: Task = {
          ...foundTask,
          status: 'completed',
          completed_at: now,
          closed_reason: options.reason || null,
          started_at: foundTask.started_at || now, // Set started_at if not already
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-complete', foundTask.slugs[0] || index.shortUlid(foundTask._ulid), options.reason);
        success(`Completed task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });

        // Output commit guidance (suppressed in JSON mode)
        if (!isJsonMode()) {
          const guidance = formatCommitGuidance(updatedTask);
          printCommitGuidance(guidance);
        }

        // Sync spec implementation status (unless --no-sync)
        if (options.sync !== false && foundTask.spec_ref) {
          // Update task list to reflect the change we just made
          const updatedTasks = tasks.map(t =>
            t._ulid === updatedTask._ulid ? { ...t, ...updatedTask } : t
          );
          const syncResult = await syncSpecImplementationStatus(
            ctx,
            updatedTask as LoadedTask,
            updatedTasks as LoadedTask[],
            items,
            index
          );
          if (syncResult) {
            info(`Synced spec "${syncResult.specTitle}" implementation: ${syncResult.previousStatus} -> ${syncResult.newStatus}`);
          }
        }
      } catch (err) {
        error('Failed to complete task', err);
        process.exit(1);
      }
    });

  // kspec task block <ref>
  task
    .command('block <ref>')
    .description('Block a task')
    .requiredOption('--reason <reason>', 'Reason for blocking')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status === 'completed' || foundTask.status === 'cancelled') {
          error(`Cannot block task with status: ${foundTask.status}`);
          process.exit(4);
        }

        const updatedTask: Task = {
          ...foundTask,
          status: 'blocked',
          blocked_by: [...foundTask.blocked_by, options.reason],
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-block', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Blocked task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });
      } catch (err) {
        error('Failed to block task', err);
        process.exit(1);
      }
    });

  // kspec task unblock <ref>
  task
    .command('unblock <ref>')
    .description('Unblock a task')
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status !== 'blocked') {
          warn('Task is not blocked');
          return;
        }

        const updatedTask: Task = {
          ...foundTask,
          status: 'pending',
          blocked_by: [],
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-unblock', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Unblocked task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });
      } catch (err) {
        error('Failed to unblock task', err);
        process.exit(1);
      }
    });

  // kspec task cancel <ref>
  task
    .command('cancel <ref>')
    .description('Cancel a task')
    .option('--reason <reason>', 'Cancellation reason')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status === 'completed' || foundTask.status === 'cancelled') {
          warn(`Task is already ${foundTask.status}`);
          return;
        }

        const updatedTask: Task = {
          ...foundTask,
          status: 'cancelled',
          closed_reason: options.reason || null,
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-cancel', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Cancelled task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });
      } catch (err) {
        error('Failed to cancel task', err);
        process.exit(1);
      }
    });

  // kspec task delete <ref>
  task
    .command('delete <ref>')
    .description('Delete a task permanently')
    .option('--force', 'Skip confirmation')
    .option('--dry-run', 'Show what would be deleted without deleting')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        const taskDisplay = `${foundTask.title} (${index.shortUlid(foundTask._ulid)})`;

        if (options.dryRun) {
          info(`Would delete task: ${taskDisplay}`);
          console.log(`  Source file: ${foundTask._sourceFile}`);
          console.log(`  Status: ${foundTask.status}`);
          if (foundTask.notes.length > 0) {
            console.log(`  Notes: ${foundTask.notes.length}`);
          }
          return;
        }

        // Confirm unless --force
        if (!options.force) {
          const readline = await import('readline');
          const rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
          });

          const answer = await new Promise<string>((resolve) => {
            rl.question(`Delete task "${taskDisplay}"? [y/N] `, resolve);
          });
          rl.close();

          if (answer.toLowerCase() !== 'y') {
            info('Deletion cancelled');
            return;
          }
        }

        await deleteTask(ctx, foundTask);
        await commitIfShadow(ctx.shadow, 'task-delete', foundTask.slugs[0] || index.shortUlid(foundTask._ulid), foundTask.title);
        success(`Deleted task: ${taskDisplay}`);
      } catch (err) {
        error('Failed to delete task', err);
        process.exit(1);
      }
    });

  // kspec task note <ref> <message>
  task
    .command('note <ref> <message>')
    .description('Add a note to a task')
    .option('--author <author>', 'Note author')
    .option('--supersedes <ulid>', 'ULID of note this supersedes')
    .action(async (ref: string, message: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        const note = createNote(message, options.author, options.supersedes);

        const updatedTask: Task = {
          ...foundTask,
          notes: [...foundTask.notes, note],
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-note', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Added note to task: ${index.shortUlid(updatedTask._ulid)}`, { note });

        // Proactive alignment guidance for tasks with spec_ref
        if (foundTask.spec_ref) {
          console.log('');
          console.log('\x1b[33m--- Alignment Check ---\x1b[0m');
          console.log('Did your implementation add anything beyond the original spec?');
          console.log('If so, consider updating the spec:');
          console.log(`  kspec item set ${foundTask.spec_ref} --description "Updated description"`);
          console.log('Or add acceptance criteria for new features.');

          // Check if linked spec has acceptance criteria and remind about test coverage
          const specResult = index.resolve(foundTask.spec_ref);
          if (specResult.ok && specResult.item) {
            const specItem = specResult.item as { acceptance_criteria?: unknown[] };
            if (specItem.acceptance_criteria && specItem.acceptance_criteria.length > 0) {
              console.log('');
              console.log(`Linked spec has ${specItem.acceptance_criteria.length} acceptance criteria - consider test coverage.`);
            }
          }
        }
      } catch (err) {
        error('Failed to add note', err);
        process.exit(1);
      }
    });

  // kspec task notes <ref>
  task
    .command('notes <ref>')
    .description('Show notes for a task')
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        output(foundTask.notes, () => {
          if (foundTask.notes.length === 0) {
            console.log('No notes');
          } else {
            for (const note of foundTask.notes) {
              const author = note.author || 'unknown';
              console.log(`[${note.created_at}] ${author}:`);
              console.log(note.content);
              console.log('');
            }
          }
        });
      } catch (err) {
        error('Failed to get notes', err);
        process.exit(1);
      }
    });

  // kspec task todos <ref>
  task
    .command('todos <ref>')
    .description('Show todos for a task')
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        output(foundTask.todos, () => {
          if (foundTask.todos.length === 0) {
            console.log('No todos');
          } else {
            for (const todo of foundTask.todos) {
              const status = todo.done ? '[x]' : '[ ]';
              const doneInfo = todo.done && todo.done_at ? ` (done ${todo.done_at})` : '';
              console.log(`${status} ${todo.id}. ${todo.text}${doneInfo}`);
            }
          }
        });
      } catch (err) {
        error('Failed to get todos', err);
        process.exit(1);
      }
    });

  // Create subcommand group for todo operations
  const todoCmd = task
    .command('todo')
    .description('Manage task todos');

  // kspec task todo add <ref> <text>
  todoCmd
    .command('add <ref> <text>')
    .description('Add a todo to a task')
    .option('--author <author>', 'Todo author')
    .action(async (ref: string, text: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        // Calculate next ID (max existing + 1, or 1 if none)
        const nextId = foundTask.todos.length > 0
          ? Math.max(...foundTask.todos.map(t => t.id)) + 1
          : 1;

        const todo = createTodo(nextId, text, options.author);

        const updatedTask: Task = {
          ...foundTask,
          todos: [...foundTask.todos, todo],
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-note', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Added todo #${todo.id} to task: ${index.shortUlid(updatedTask._ulid)}`, { todo });
      } catch (err) {
        error('Failed to add todo', err);
        process.exit(1);
      }
    });

  // kspec task todo done <ref> <id>
  todoCmd
    .command('done <ref> <id>')
    .description('Mark a todo as done')
    .action(async (ref: string, idStr: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        const id = parseInt(idStr, 10);
        if (isNaN(id)) {
          error(`Invalid todo ID: ${idStr}`);
          process.exit(3);
        }

        const todoIndex = foundTask.todos.findIndex(t => t.id === id);
        if (todoIndex === -1) {
          error(`Todo #${id} not found`);
          process.exit(3);
        }

        if (foundTask.todos[todoIndex].done) {
          warn(`Todo #${id} is already done`);
          return;
        }

        const updatedTodos = [...foundTask.todos];
        updatedTodos[todoIndex] = {
          ...updatedTodos[todoIndex],
          done: true,
          done_at: new Date().toISOString(),
        };

        const updatedTask: Task = {
          ...foundTask,
          todos: updatedTodos,
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-note', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Marked todo #${id} as done`, { todo: updatedTodos[todoIndex] });
      } catch (err) {
        error('Failed to mark todo as done', err);
        process.exit(1);
      }
    });

  // kspec task todo undone <ref> <id>
  todoCmd
    .command('undone <ref> <id>')
    .description('Mark a todo as not done')
    .action(async (ref: string, idStr: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        const id = parseInt(idStr, 10);
        if (isNaN(id)) {
          error(`Invalid todo ID: ${idStr}`);
          process.exit(3);
        }

        const todoIndex = foundTask.todos.findIndex(t => t.id === id);
        if (todoIndex === -1) {
          error(`Todo #${id} not found`);
          process.exit(3);
        }

        if (!foundTask.todos[todoIndex].done) {
          warn(`Todo #${id} is not done`);
          return;
        }

        const updatedTodos = [...foundTask.todos];
        updatedTodos[todoIndex] = {
          ...updatedTodos[todoIndex],
          done: false,
          done_at: undefined,
        };

        const updatedTask: Task = {
          ...foundTask,
          todos: updatedTodos,
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-note', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Marked todo #${id} as not done`, { todo: updatedTodos[todoIndex] });
      } catch (err) {
        error('Failed to mark todo as not done', err);
        process.exit(1);
      }
    });
}

import chalk from 'chalk';
import type { Task, TaskStatus } from '../schema/index.js';
import type { ReferenceIndex } from '../parser/index.js';
import { grepItem, formatMatchedFields } from '../utils/grep.js';

/**
 * Output options
 */
export interface OutputOptions {
  json?: boolean;
}

/**
 * Global output format (set by --json flag)
 */
let globalJsonMode = false;

export function setJsonMode(enabled: boolean): void {
  globalJsonMode = enabled;
}

export function isJsonMode(): boolean {
  return globalJsonMode;
}

/**
 * Output data - JSON if --json flag, otherwise formatted
 */
export function output(data: unknown, formatter?: () => void): void {
  if (globalJsonMode) {
    console.log(JSON.stringify(data, null, 2));
  } else if (formatter) {
    formatter();
  } else {
    console.log(data);
  }
}

/**
 * Output success message
 */
export function success(message: string, data?: Record<string, unknown>): void {
  if (globalJsonMode) {
    console.log(JSON.stringify({ success: true, message, ...data }));
  } else {
    console.log(chalk.green('OK'), message);
  }
}

/**
 * Output error message
 */
export function error(message: string, details?: unknown): void {
  if (globalJsonMode) {
    console.error(JSON.stringify({ success: false, error: message, details }));
  } else {
    console.error(chalk.red('✗'), message);
    if (details) {
      console.error(chalk.gray(String(details)));
    }
  }
}

/**
 * Output warning message
 */
export function warn(message: string): void {
  if (globalJsonMode) {
    // Warnings are suppressed in JSON mode
  } else {
    console.warn(chalk.yellow('⚠'), message);
  }
}

/**
 * Output info message
 */
export function info(message: string): void {
  if (globalJsonMode) {
    // Info messages suppressed in JSON mode
  } else {
    console.log(chalk.blue('ℹ'), message);
  }
}

/**
 * Get color for task status
 */
function statusColor(status: TaskStatus): (text: string) => string {
  switch (status) {
    case 'pending':
      return (t: string) => chalk.gray(t);
    case 'in_progress':
      return (t: string) => chalk.blue(t);
    case 'blocked':
      return (t: string) => chalk.red(t);
    case 'completed':
      return (t: string) => chalk.green(t);
    case 'cancelled':
      return (t: string) => chalk.strikethrough.gray(t);
    default:
      return (t: string) => chalk.white(t);
  }
}

/**
 * Format a task reference (short ULID + slug if available)
 * @param task The task to format
 * @param index Optional ReferenceIndex for dynamic short ULID computation
 */
export function formatTaskRef(task: Task, index?: ReferenceIndex): string {
  const shortId = index ? index.shortUlid(task._ulid) : task._ulid.slice(0, 8);
  if (task.slugs.length > 0) {
    return `${shortId} (${task.slugs[0]})`;
  }
  return shortId;
}

/**
 * Format task for display
 */
export function formatTask(task: Task, verbose = false, index?: ReferenceIndex): string {
  const ref = formatTaskRef(task, index);
  const status = statusColor(task.status)(`[${task.status}]`);
  const priority = task.priority <= 2 ? chalk.red(`P${task.priority}`) : chalk.gray(`P${task.priority}`);

  let line = `${ref} ${status} ${priority} ${task.title}`;

  if (verbose) {
    if (task.spec_ref) {
      line += chalk.gray(` (spec: ${task.spec_ref})`);
    }
    if (task.depends_on.length > 0) {
      line += chalk.gray(` deps: [${task.depends_on.join(', ')}]`);
    }
    if (task.tags.length > 0) {
      line += chalk.cyan(` #${task.tags.join(' #')}`);
    }
  }

  return line;
}

/**
 * Get first line of text, truncated to max length
 */
function getFirstLine(text: string | undefined, maxLength: number = 70): string | undefined {
  if (!text) return undefined;
  const firstLine = text.split('\n')[0].trim();
  if (firstLine.length <= maxLength) return firstLine;
  return firstLine.slice(0, maxLength - 3) + '...';
}

/**
 * Format a list of tasks
 */
export function formatTaskList(tasks: Task[], verbose = false, index?: ReferenceIndex, grepPattern?: string): void {
  if (tasks.length === 0) {
    console.log(chalk.gray('No tasks found'));
    return;
  }

  for (const task of tasks) {
    console.log(formatTask(task, verbose, index));

    // Show matched fields if grep pattern provided
    if (grepPattern) {
      const match = grepItem(task as unknown as Record<string, unknown>, grepPattern);
      if (match && match.matchedFields.length > 0) {
        console.log(chalk.gray(`    matched: ${formatMatchedFields(match.matchedFields)}`));
      }
    } else {
      // Show context line: first line of description (if present)
      const context = getFirstLine(task.description);
      if (context) {
        console.log(chalk.gray(`    ${context}`));
      }
    }
  }

  console.log(chalk.gray(`\n${tasks.length} task(s)`));
}

/**
 * Format task details
 */
export function formatTaskDetails(task: Task, index?: ReferenceIndex): void {
  console.log(chalk.bold(task.title));
  console.log(chalk.gray('─'.repeat(40)));
  console.log(`ULID:      ${task._ulid}`);
  if (task.slugs.length > 0) {
    console.log(`Slugs:     ${task.slugs.join(', ')}`);
  }
  console.log(`Type:      ${task.type}`);
  console.log(`Status:    ${statusColor(task.status)(task.status)}`);
  console.log(`Priority:  ${task.priority}`);

  if (task.spec_ref) {
    console.log(`Spec ref:  ${task.spec_ref}`);
  }

  if (task.depends_on.length > 0) {
    if (index) {
      console.log(`Depends:`);
      for (const ref of task.depends_on) {
        const result = index.resolve(ref);
        if (result.ok) {
          const item = result.item;
          const status = 'status' in item && typeof item.status === 'string'
            ? statusColor(item.status as TaskStatus)(`[${item.status}]`)
            : chalk.gray('[spec]');
          // Handle both spec items (with title) and meta items (with name or id)
          const itemName = 'title' in item ? item.title : ('name' in item ? item.name : ('id' in item ? item.id : ref));
          console.log(`  ${ref} ${chalk.gray('→')} ${itemName} ${status}`);
        } else {
          console.log(`  ${ref} ${chalk.red('(unresolved)')}`);
        }
      }
    } else {
      console.log(`Depends:   ${task.depends_on.join(', ')}`);
    }
  }

  if (task.blocked_by.length > 0) {
    console.log(chalk.red(`Blocked:   ${task.blocked_by.join(', ')}`));
  }

  if (task.tags.length > 0) {
    console.log(`Tags:      ${task.tags.join(', ')}`);
  }

  console.log(`Created:   ${task.created_at}`);
  if (task.started_at) {
    console.log(`Started:   ${task.started_at}`);
  }
  if (task.completed_at) {
    console.log(`Completed: ${task.completed_at}`);
  }

  // Show resolved spec information
  if (task.spec_ref && index) {
    const result = index.resolve(task.spec_ref);
    if (result.ok) {
      const spec = result.item;
      console.log(chalk.gray('\n─── Spec Context ───'));
      // Handle both spec items (with title) and meta items (with name)
      const specName = 'title' in spec ? spec.title : ('name' in spec ? spec.name : ('id' in spec ? spec.id : task.spec_ref));
      console.log(chalk.cyan(specName));
      if ('type' in spec && spec.type) {
        console.log(chalk.gray(`Type: ${spec.type}`));
      }
      // Show implementation status
      if ('status' in spec && spec.status && typeof spec.status === 'object') {
        const status = spec.status as { maturity?: string; implementation?: string };
        if (status.implementation) {
          const implColor = status.implementation === 'verified' ? chalk.green
            : status.implementation === 'implemented' ? chalk.cyan
            : status.implementation === 'in_progress' ? chalk.yellow
            : chalk.gray;
          console.log(chalk.gray('Implementation: ') + implColor(status.implementation));
        }
      }
      if ('description' in spec && spec.description) {
        console.log(chalk.gray('Description:'));
        // Indent description lines
        const desc = String(spec.description).trim();
        for (const line of desc.split('\n')) {
          console.log(chalk.gray(`  ${line}`));
        }
      }
      if ('acceptance_criteria' in spec && Array.isArray(spec.acceptance_criteria) && spec.acceptance_criteria.length > 0) {
        console.log(chalk.gray('Acceptance Criteria:'));
        for (const ac of spec.acceptance_criteria) {
          if (ac && typeof ac === 'object' && 'id' in ac) {
            const acObj = ac as { id: string; given?: string; when?: string; then?: string };
            console.log(chalk.gray(`  [${acObj.id}]`));
            if (acObj.given) console.log(chalk.gray(`    Given: ${acObj.given}`));
            if (acObj.when) console.log(chalk.gray(`    When: ${acObj.when}`));
            if (acObj.then) console.log(chalk.gray(`    Then: ${acObj.then}`));
          }
        }
      }
      // Show traceability if present
      if ('traceability' in spec && spec.traceability && typeof spec.traceability === 'object') {
        const trace = spec.traceability as {
          implementation?: Array<{ path: string; function?: string; lines?: string }>;
          tests?: Array<{ path: string }>;
          commits?: string[];
          issues?: string[];
        };
        const hasTrace = trace.implementation?.length || trace.tests?.length || trace.commits?.length || trace.issues?.length;
        if (hasTrace) {
          console.log(chalk.gray('Traceability:'));
          if (trace.implementation?.length) {
            for (const impl of trace.implementation) {
              let loc = `  Code: ${impl.path}`;
              if (impl.function) loc += `::${impl.function}`;
              if (impl.lines) loc += `:${impl.lines}`;
              console.log(chalk.gray(loc));
            }
          }
          if (trace.tests?.length) {
            for (const test of trace.tests) {
              console.log(chalk.gray(`  Test: ${test.path}`));
            }
          }
          if (trace.commits?.length) {
            console.log(chalk.gray(`  Commits: ${trace.commits.join(', ')}`));
          }
          if (trace.issues?.length) {
            console.log(chalk.gray(`  Issues: ${trace.issues.join(', ')}`));
          }
        }
      }
    }
  }

  if (task.notes.length > 0) {
    console.log(chalk.gray('\n─── Notes ───'));
    for (const note of task.notes) {
      const author = note.author || 'unknown';
      console.log(chalk.gray(`[${note.created_at}] ${author}:`));
      console.log(note.content);
    }
  }

  if (task.todos.length > 0) {
