  SHADOW_WORKTREE_DIR,
} from '../../parser/shadow.js';

/**
 * Default manifest template
 */
function generateManifest(projectName: string, singleFile: boolean): string {
  const lines = [
    `# ${projectName} - Kynetic Spec`,
    `# Generated by kspec init`,
    ``,
    `kynetic: "1.0"`,
    ``,
    `project:`,
    `  name: "${projectName}"`,
    `  version: "0.1.0"`,
    `  status: draft`,
    `  description: |`,
    `    Add your project description here.`,
    ``,
  ];

  if (!singleFile) {
    lines.push(
      `# Module includes - add your spec modules here`,
      `includes:`,
      `  - modules/main.yaml`,
      ``,
    );
  }

  lines.push(
    `# Configuration`,
    `config:`,
    `  validation:`,
    `    strict_refs: true`,
    `    require_acceptance: false`,
    ``,
  );

  return lines.join('\n');
}

/**
