  noSpecRef: {
    warning: chalk.yellow("This task has no spec_ref."),
    consider: chalk.gray("Is this a spec gap? Consider: kspec item add --under @parent ..."),
    intentional: chalk.gray("Or is this intentional (infra/cleanup)?"),
  },
} as const;

/**
