  },

  uncommittedChanges: {
    header: chalk.yellow('\n3. Uncommitted Changes:'),
    action: chalk.gray('   Commit your work or create a WIP commit:'),
    wipCommit: chalk.gray(`   git add -A && git commit -m "WIP: describe state\n\n   Task: @task-ref"`),
