cat << 'EOF' > /tmp/verify-strings.mjs
import chalk from 'chalk';

const alignmentCheck = {
  header: chalk.gray('--- Alignment Check ---'),
  beyondSpec: chalk.gray('Did your implementation add anything beyond the original spec?'),
  updateSpec: (specRef) =>
    chalk.gray(`If so, consider updating the spec:\n  kspec item set ${specRef} --description "Updated description"`),
  addAC: chalk.gray('Or add acceptance criteria for new features.'),
  testCoverage: (count) =>
    chalk.gray(`Linked spec has ${count} acceptance criteria - consider test coverage.`),
};

// Original strings (without color)
const original = {
  header: '--- Alignment Check ---',
  beyondSpec: 'Did your implementation add anything beyond the original spec?',
  updateSpec: (ref) => `If so, consider updating the spec:\n  kspec item set ${ref} --description "Updated description"`,
  addAC: 'Or add acceptance criteria for new features.',
  testCoverage: (count) => `Linked spec has ${count} acceptance criteria - consider test coverage.`,
};

// Test with example ref
const testRef = '@test-spec';
const testCount = 5;

console.log('=== Text Content Comparison ===');
console.log('Header match:', alignmentCheck.header.includes(original.header));
console.log('BeyondSpec match:', alignmentCheck.beyondSpec.includes(original.beyondSpec));
console.log('UpdateSpec match:', alignmentCheck.updateSpec(testRef).includes(original.updateSpec(testRef)));
console.log('AddAC match:', alignmentCheck.addAC.includes(original.addAC));
console.log('TestCoverage match:', alignmentCheck.testCoverage(testCount).includes(original.testCoverage(testCount)));

console.log('\n=== Original vs New ===');
console.log('Original updateSpec:\n', original.updateSpec(testRef));
console.log('\nNew updateSpec (stripped):\n', alignmentCheck.updateSpec(testRef).replace(/\x1b\[[0-9;]*m/g, ''));
EOF
node /tmp/verify-strings.mjs

