   168→            console.log(shadowCommands.log.repairHint);
   169→          }
   170→          process.exit(1);
   171→        }
   172→
   173→        const count = parseInt(options.count, 10) || 10;
   174→
   175→        const log = execSync(
   176→          `git log --oneline -n ${count} ${SHADOW_BRANCH_NAME}`,
   177→          { cwd: gitRoot, encoding: 'utf-8' }
   178→        ).trim();
   179→
   180→        if (!log) {
   181→          info(shadowCommands.log.noCommits);
   182→          return;
   183→        }
   184→
   185→        console.log(chalk.bold(`Recent commits on ${SHADOW_BRANCH_NAME}:`));
   186→        console.log(chalk.gray('─'.repeat(40)));
   187→        console.log(log);
   188→      } catch (err) {
   189→        error(shadowCommands.log.failed, err);
   190→        process.exit(1);
   191→      }
   192→    });
   193→
   194→  // AC-5: Shadow resolve command for conflict resolution
   195→  shadow
   196→    .command('resolve')
   197→    .description('Resolve shadow branch sync conflicts')
   198→    .option('--theirs', 'Accept all remote changes, discard local')
   199→    .option('--ours', 'Keep all local changes, discard remote')
   200→    .action(async (options) => {
   201→      try {
   202→        const gitRoot = getGitRoot(process.cwd());
   203→
   204→        if (!gitRoot) {
   205→          error(shadowCommands.notGitRepo);
   206→          process.exit(1);
   207→        }
   208→
   209→        const status = await getShadowStatus(gitRoot);
   210→
   211→        if (!status.healthy) {
   212→          error(shadowCommands.resolve.notHealthy);
   213→          console.log(shadowCommands.resolve.repairHint);
   214→          process.exit(1);
   215→        }
   216→
   217→        const worktreeDir = `${gitRoot}/${SHADOW_WORKTREE_DIR}`;
   218→
   219→        // Check if there's a rebase in progress
   220→        let inRebase = false;
   221→        try {
   222→          execSync('git rebase --show-current-patch', {
   223→            cwd: worktreeDir,
   224→            stdio: ['pipe', 'pipe', 'pipe'],
   225→          });
   226→          inRebase = true;
   227→        } catch {
   228→          // Not in rebase
   229→        }
   230→
   231→        if (options.theirs) {
   232→          // Accept remote changes
   233→          info(shadowCommands.resolve.acceptingRemote);
   234→          if (inRebase) {
   235→            execSync('git rebase --abort', { cwd: worktreeDir, stdio: 'inherit' });
   236→          }
   237→          execSync(`git fetch origin ${SHADOW_BRANCH_NAME}`, { cwd: worktreeDir, stdio: 'inherit' });
   238→          execSync(`git reset --hard origin/${SHADOW_BRANCH_NAME}`, { cwd: worktreeDir, stdio: 'inherit' });
   239→          success(shadowCommands.resolve.acceptedRemote);
   240→        } else if (options.ours) {
   241→          // Keep local changes
   242→          info(shadowCommands.resolve.keepingLocal);
   243→          if (inRebase) {
   244→            execSync('git rebase --abort', { cwd: worktreeDir, stdio: 'inherit' });
   245→          }
   246→          // Force push to override remote
   247→          try {
   248→            execSync('git push --force-with-lease', { cwd: worktreeDir, stdio: 'inherit' });
   249→            success(shadowCommands.resolve.keptLocal);
   250→          } catch {
   251→            warn(shadowCommands.resolve.pushFailed);
   252→            console.log(shadowCommands.resolve.localPreserved);
   253→          }
   254→        } else {
   255→          // Interactive guidance
   256→          console.log(shadowCommands.resolve.interactive.header);
   257→          console.log(shadowCommands.resolve.interactive.separator);
   258→
   259→          if (inRebase) {
   260→            console.log(shadowCommands.resolve.interactive.rebaseInProgress);
   261→            console.log();
   262→          }
   263→
   264→          console.log(shadowCommands.resolve.interactive.options);
   265→          console.log();
   266→          console.log(shadowCommands.resolve.interactive.theirs.command);
   267→          console.log(shadowCommands.resolve.interactive.theirs.description);
   268→          console.log();
   269→          console.log(shadowCommands.resolve.interactive.ours.command);
   270→          console.log(shadowCommands.resolve.interactive.ours.description);
   271→          console.log();
   272→          console.log(shadowCommands.resolve.interactive.manual.header);
   273→          console.log(shadowCommands.resolve.interactive.manual.cdCommand(SHADOW_WORKTREE_DIR));
   274→          if (inRebase) {
   275→            shadowCommands.resolve.interactive.manual.rebaseSteps.forEach((step) => console.log(step));
   276→          } else {
   277→            shadowCommands.resolve.interactive.manual.pullSteps.forEach((step) => console.log(step));
   278→          }
   279→        }
   280→      } catch (err) {
   281→        error(shadowCommands.resolve.failed, err);
   282→        process.exit(1);
   283→      }
   284→    });
   285→
   286→  // Explicit sync command
   287→  shadow
   288→    .command('sync')
   289→    .description('Manually sync shadow branch with remote (pull then push)')
   290→    .action(async () => {
   291→      try {
   292→        const gitRoot = getGitRoot(process.cwd());
   293→
   294→        if (!gitRoot) {
   295→          error(shadowCommands.notGitRepo);
   296→          process.exit(1);
   297→        }
   298→
   299→        const status = await getShadowStatus(gitRoot);
   300→
   301→        if (!status.healthy) {
   302→          error(shadowCommands.sync.notHealthy);
   303→          console.log(shadowCommands.sync.repairHint);
   304→          process.exit(1);
   305→        }
   306→
   307→        const worktreeDir = `${gitRoot}/${SHADOW_WORKTREE_DIR}`;
   308→
   309→        if (!(await hasRemoteTracking(worktreeDir))) {
   310→          info(shadowCommands.sync.noRemote);
   311→          console.log(shadowCommands.sync.localOnly);
   312→          return;
   313→        }
   314→
   315→        info(shadowCommands.sync.syncing);
   316→
   317→        const result = await shadowSync(worktreeDir);
   318→
   319→        if (result.hadConflict) {
   320→          warn(shadowCommands.sync.conflictDetected);
   321→          console.log(shadowCommands.sync.resolveHint);
   322→          process.exit(1);
   323→        }
   324→
   325→        if (result.pulled && result.pushed) {
   326→          success(shadowCommands.sync.syncedBoth);
   327→        } else if (result.pulled) {
   328→          success(shadowCommands.sync.syncedPull);
   329→        } else if (result.pushed) {
   330→          success(shadowCommands.sync.syncedPush);
   331→        } else {
   332→          info(shadowCommands.sync.alreadyInSync);
   333→        }
   334→      } catch (err) {
   335→        error(shadowCommands.sync.failed, err);
   336→        process.exit(1);
   337→      }
   338→    });
   339→}
