    60→interface SearchResult {
    61→  type: 'item' | 'task';
    62→  item: LoadedSpecItem | LoadedTask;
    63→  matchedFields: string[];
    64→}
    65→
    66→/**
    67→ * Register the search command
    68→ */
    69→export function registerSearchCommand(program: Command): void {
    70→  program
    71→    .command('search <pattern>')
    72→    .description('Search across all items and tasks with regex pattern')
    73→    .option('-t, --type <type>', 'Filter by item type')
    74→    .option('-s, --status <status>', 'Filter by task status')
    75→    .option('--items-only', 'Search only spec items')
    76→    .option('--tasks-only', 'Search only tasks')
    77→    .option('--limit <n>', 'Limit results', '50')
    78→    .action(async (pattern, options) => {
    79→      try {
    80→        const ctx = await initContext();
    81→        const { itemIndex, tasks, items, refIndex } = await buildIndexes(ctx);
    82→
    83→        const results: SearchResult[] = [];
    84→        const limit = parseInt(options.limit, 10) || 50;
    85→
    86→        // Search spec items
    87→        if (!options.tasksOnly) {
    88→          for (const item of items) {
    89→            // Apply type filter
    90→            if (options.type && item.type !== options.type) continue;
    91→
    92→            const match = grepItem(item as unknown as Record<string, unknown>, pattern);
    93→            if (match) {
    94→              results.push({
    95→                type: 'item',
    96→                item,
    97→                matchedFields: match.matchedFields,
    98→              });
    99→            }
   100→          }
   101→        }
   102→
   103→        // Search tasks
   104→        if (!options.itemsOnly) {
   105→          for (const task of tasks) {
   106→            // Apply status filter
   107→            if (options.status && task.status !== options.status) continue;
   108→
   109→            const match = grepItem(task as unknown as Record<string, unknown>, pattern);
   110→            if (match) {
   111→              results.push({
   112→                type: 'task',
   113→                item: task,
   114→                matchedFields: match.matchedFields,
   115→              });
   116→            }
   117→          }
   118→        }
   119→
   120→        // Limit results
   121→        const limitedResults = results.slice(0, limit);
   122→
   123→        output(
   124→          {
   125→            pattern,
   126→            results: limitedResults.map(r => ({
   127→              type: r.type,
   128→              ulid: r.item._ulid,
   129→              title: r.item.title,
   130→              matchedFields: r.matchedFields,
   131→            })),
   132→            total: results.length,
   133→            showing: limitedResults.length,
   134→          },
   135→          () => {
   136→            if (limitedResults.length === 0) {
   137→              console.log(chalk.gray(`No matches found for "${pattern}"`));
   138→              return;
   139→            }
   140→
   141→            for (const result of limitedResults) {
   142→              if (result.type === 'item') {
   143→                formatSearchItem(result.item as LoadedSpecItem, result.matchedFields);
   144→              } else {
   145→                formatSearchTask(result.item as LoadedTask, result.matchedFields);
   146→              }
   147→            }
   148→
   149→            console.log(chalk.gray(`\n${limitedResults.length} result(s)${results.length > limit ? ` (showing first ${limit})` : ''}`));
   150→          }
   151→        );
   152→      } catch (err) {
   153→        error('Failed to search', err);
   154→        process.exit(1);
   155→      }
   156→    });
