                  cwd: process.cwd(),
                  mcpServers: [], // No MCP servers for now
                });

                info('Sending prompt to agent...');

                // Send prompt and wait for completion
                const response = await agent.client.prompt({
                  sessionId: acpSessionId!,
                  prompt: [{ type: 'text', text: prompt }],
                });

                // Log completion
                await appendEvent(specDir, {
                  session_id: sessionId,
                  type: 'session.update',
                  data: {
                    iteration,
                    stopReason: response.stopReason,
                    completed: true,
                  },
                });

                // Check stop reason
                if (response.stopReason === 'cancelled') {
                  throw new Error('Agent prompt was cancelled');
                }

                succeeded = true;
                break;
              } catch (err) {
                lastError = err as Error;
                error(errors.failures.ralphIteration, lastError);

                // Clean up agent on error - will respawn next attempt
                if (agent) {
                  agent.kill();
                  agent = null;
                  acpSessionId = null;
                }
              }
            }

            if (succeeded) {
              success(`Completed iteration ${iteration}`);
              consecutiveFailures = 0;
              console.log(); // Newline after streaming output
            } else {
              consecutiveFailures++;
              error(errors.failures.ralphIterationRetries(iteration, maxRetries + 1, consecutiveFailures, maxFailures));
              if (lastError) {
                error(errors.failures.ralphLastError, lastError);
              }

              if (consecutiveFailures >= maxFailures) {
                error(errors.failures.ralphMaxFailures(maxFailures));
                break;
              }

              info('Continuing to next iteration...');
            }
          }
        } finally {
          // Clean up agent
          if (agent) {
            agent.kill();
          }

          // Log session end
          const status = consecutiveFailures >= maxFailures ? 'abandoned' : 'completed';
          await appendEvent(specDir, {
            session_id: sessionId,
            type: 'session.end',
            data: {
              status,
              consecutiveFailures,
            },
          });
          await updateSessionStatus(specDir, sessionId, status);
        }

        console.log(chalk.green(`\n${'─'.repeat(60)}`));
        success('Ralph loop completed');
        console.log(chalk.green(`${'─'.repeat(60)}\n`));

      } catch (err) {
        error(errors.failures.ralphLoop, err);
        process.exit(1);
      }
    });
}

